({
  async init(msg) {
    if (!this.data) {
      this.data = { latestReport: null };
    }
    this._checkInvariants();
    return { ok: true };
  },

  async fetchWeather(msg) {
    // Precondition
    const city = msg?.payload?.city;
    this.ensure(
      typeof city === "string" && city.trim().length > 0,
      "A non-empty city name string is required in msg.payload.city"
    );

    const trimmedCity = city.trim();
    const httpId = await this.dep("HttpClient");
    this.ensure(Boolean(httpId), "HttpClient dependency could not be resolved");

    const url = `https://api.weather.test/forecast?city=${encodeURIComponent(trimmedCity)}`;
    const response = await this.call(httpId, "get", { url });

    let payload = response;
    if (response && typeof response === "object" && "body" in response) {
      payload = typeof response.body === "string" ? JSON.parse(response.body) : response.body;
    } else if (typeof response === "string") {
      payload = JSON.parse(response);
    }

    this.ensure(payload && typeof payload === "object", "Weather API response must be a valid JSON object");

    const report = {
      city: trimmedCity,
      temperature: payload.temperature ?? payload.temp ?? payload.current?.temperature ?? null,
      humidity: payload.humidity ?? payload.current?.humidity ?? null,
      conditions: payload.conditions ?? payload.condition ?? payload.weather ?? "Unknown",
      forecast: payload.forecast ?? null,
      fetchedAt: new Date().toISOString()
    };

    // Apply mutation
    this._setLatestReport(report);

    // Postcondition
    this.ensure(
      this.data.latestReport && this.data.latestReport.city === trimmedCity,
      "Latest weather report must be stored in this.data"
    );

    return this.data.latestReport;
  },

  async getLatestReport(msg) {
    return this.data?.latestReport ?? null;
  },

  _setLatestReport(report) {
    if (!this.data) {
      this.data = {};
    }
    this.data.latestReport = report;
    this._checkInvariants();
    this.changed("latestReport", report);
  },

  _checkInvariants() {
    if (this.data) {
      this.invariant(typeof this.data === "object", "this.data must be an object");
      if (this.data.latestReport !== null && this.data.latestReport !== undefined) {
        this.invariant(typeof this.data.latestReport === "object", "latestReport must be an object");
        this.invariant(typeof this.data.latestReport.city === "string", "latestReport.city must be a string");
      }
    }
  }
})
